/**
 * PRIMEMET — shared machinery for the M1 verification harness.
 *
 * What this provides, and why each part exists:
 *
 *   - An **isolated** MongoDB: `mongodb-memory-server` as a single-node replica set, because account
 *     registration uses a transaction and a standalone server cannot run one. Nothing here can reach a
 *     configured or production cluster: the URI is generated by the in-memory server, never read from
 *     the environment.
 *   - The **real migrations** (`db/migrations` + `db/ledger.mjs`), applied to that instance through the
 *     same code the CLI uses.
 *   - The **real application** served by `next start` from the production build, so the tests exercise
 *     middleware, route handlers, cookies and the data layer exactly as a deployment does.
 *   - A tiny cookie-aware HTTP client. Node's fetch has no cookie jar, and the harness must be able to
 *     inspect and tamper with the cookie, which a jar constant would take away.
 *
 * The harness prints every test with its observed result and exits non-zero on any failure, so the
 * exit code is the verdict rather than a sentence in a log.
 */

import { spawn } from "node:child_process";
import { createWriteStream, existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import process from "node:process";

import { MongoClient } from "mongodb";
import { MongoMemoryReplSet } from "mongodb-memory-server";

import { MIGRATIONS } from "../../db/migrations/index.mjs";
import { applyMigrations } from "../../db/ledger.mjs";

import { fileURLToPath } from "node:url";

export const PROJECT_ROOT = path.resolve(fileURLToPath(new URL("../..", import.meta.url)));
export const APP_ORIGIN = "https://primemet.test";
export const AUTH_SECRET = "m1-verification-secret-0123456789-abcdefghijklmnop";
export const RUN_DIR = path.join(PROJECT_ROOT, ".exvisit", "tmp", "m1-verify");

export function log(line = "") {
  process.stdout.write(`${line}\n`);
}

export function ensureRunDir() {
  mkdirSync(RUN_DIR, { recursive: true });
  return RUN_DIR;
}

/* -------------------------------------------------------------------------------------------------
 * MongoDB
 * ---------------------------------------------------------------------------------------------- */

/**
 * Start the isolated replica set and return a handle.
 *
 * `MONGOMS_*` variables are left alone so an offline binary cache, when present, is used.
 */
export async function startMongo({ port } = {}) {
  const replSet = await MongoMemoryReplSet.create({
    replSet: { count: 1, storageEngine: "wiredTiger", name: "rs0" },
    instanceOpts: port ? [{ port }] : undefined,
  });
  const uri = replSet.getUri();
  const client = new MongoClient(uri, { serverSelectionTimeoutMS: 20000 });
  await client.connect();
  return {
    uri,
    client,
    async db(name) {
      return client.db(name);
    },
    async stop() {
      await client.close();
      await replSet.stop();
    },
  };
}

/** Apply the repository's migrations to one database, exactly as `npm run db:init` does. */
export async function migrate(db, { migrations = MIGRATIONS, appliedBy = "m1-verifier", log: sink } = {}) {
  return applyMigrations(db, { migrations, appliedBy, appVersion: "0.1.0", log: sink ?? (() => {}) });
}

/* -------------------------------------------------------------------------------------------------
 * Next.js server
 * ---------------------------------------------------------------------------------------------- */

function nextBin() {
  const candidates = [
    path.join(PROJECT_ROOT, "node_modules", "next", "dist", "bin", "next"),
    path.join(PROJECT_ROOT, "node_modules", ".bin", "next"),
  ];
  const found = candidates.find((candidate) => existsSync(candidate));
  if (!found) throw new Error("Next.js binary not found; run npm install first.");
  return found;
}

/**
 * The child process environment.
 *
 * Built from scratch rather than by overriding an inherited environment: a stray production connection
 * string in the operator's shell must never reach a process the tests are about to create data in. The
 * `NEXT_PUBLIC_*` value is the fake HTTPS origin, so cookie attributes are exercised as deployed.
 */
function childEnvironment(uri, dbName) {
  const environment = {};
  for (const key of ["PATH", "Path", "SYSTEMROOT", "SystemRoot", "TEMP", "TMP", "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "COMSPEC"]) {
    if (process.env[key] !== undefined) environment[key] = process.env[key];
  }
  return {
    ...environment,
    NODE_ENV: "production",
    NEXT_PUBLIC_APP_URL: APP_ORIGIN,
    MONGODB_URI: uri,
    MONGODB_DB: dbName,
    PRIMEMET_ENV: "test",
    AUTH_SECRET,
  };
}

/** Start `next start` against the isolated database and wait until /api/health answers. */
export async function startServer({ port, uri, dbName }) {
  ensureRunDir();
  const logFile = path.join(RUN_DIR, `server-${port}.log`);
  const out = createWriteStream(logFile, { flags: "w" });

  const child = spawn(process.execPath, [nextBin(), "start", "-p", String(port)], {
    cwd: PROJECT_ROOT,
    env: childEnvironment(uri, dbName),
    stdio: ["ignore", "pipe", "pipe"],
  });
  child.stdout.pipe(out);
  child.stderr.pipe(out);

  const baseUrl = `http://127.0.0.1:${port}`;
  const deadline = Date.now() + 90_000;
  let lastError = null;
  while (Date.now() < deadline) {
    if (child.exitCode !== null) {
      throw new Error(`next start exited early with code ${child.exitCode}; see ${logFile}`);
    }
    try {
      const response = await fetch(`${baseUrl}/api/health`, { redirect: "manual" });
      if (response.status >= 200 && response.status < 500) {
        return {
          baseUrl,
          logFile,
          stop: () =>
            new Promise((resolve) => {
              if (child.exitCode !== null) return resolve();
              child.once("exit", () => resolve());
              child.kill("SIGTERM");
              setTimeout(() => {
                if (child.exitCode === null) child.kill("SIGKILL");
              }, 5000).unref();
            }),
        };
      }
      lastError = new Error(`health returned ${response.status}`);
    } catch (error) {
      lastError = error;
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  child.kill("SIGKILL");
  throw new Error(`next start did not become healthy on port ${port}: ${lastError?.message ?? "timeout"}`);
}

/* -------------------------------------------------------------------------------------------------
 * HTTP client
 * ---------------------------------------------------------------------------------------------- */

/** Parse a Set-Cookie header into its attributes. */
export function parseSetCookie(header) {
  const [pair, ...attributes] = header.split(";").map((part) => part.trim());
  const separator = pair.indexOf("=");
  const cookie = {
    name: separator === -1 ? pair : pair.slice(0, separator),
    value: separator === -1 ? "" : pair.slice(separator + 1),
    raw: header,
    attributes: {},
  };
  for (const attribute of attributes) {
    const [key, ...rest] = attribute.split("=");
    cookie.attributes[key.toLowerCase()] = rest.join("=");
  }
  return cookie;
}

export function createClient(baseUrl) {
  const jar = new Map();

  async function request(method, pathname, options = {}) {
    const headers = { ...(options.headers ?? {}) };
    let body = options.body;

    if (body !== undefined && typeof body !== "string") {
      body = JSON.stringify(body);
      headers["content-type"] = headers["content-type"] ?? "application/json";
      headers.accept = headers.accept ?? "application/json";
    }
    if (!("x-forwarded-for" in headers)) headers["x-forwarded-for"] = options.ip ?? "203.0.113.7";

    // Sending cookies is the default: a client that holds a jar is a signed-in browser. An explicit
    // `cookie` header wins, because the tampering tests hand the server a cookie the jar must not
    // substitute for; `anonymous: true` withholds the jar entirely.
    if (!options.anonymous && jar.size > 0 && headers.cookie === undefined) {
      headers.cookie = [...jar.entries()].map(([name, value]) => `${name}=${value}`).join("; ");
    }

    const response = await fetch(new URL(pathname, baseUrl), {
      method,
      headers,
      body,
      redirect: "manual",
    });

    const setCookies = response.headers.getSetCookie().map(parseSetCookie);
    if (options.useJar) {
      for (const cookie of setCookies) {
        const expired = cookie.attributes["max-age"] === "0" || cookie.value === "";
        if (expired) jar.delete(cookie.name);
        else jar.set(cookie.name, cookie.value);
      }
    }

    const text = await response.text();
    let json = null;
    try {
      json = JSON.parse(text);
    } catch {
      json = null;
    }

    return {
      status: response.status,
      headers: response.headers,
      setCookies,
      text,
      json,
      location: response.headers.get("location"),
      cookie(name) {
        return setCookies.find((cookie) => cookie.name === name) ?? null;
      },
      get jar() {
        return jar;
      },
    };
  }

  return {
    baseUrl,
    jar,
    get: (pathname, options) => request("GET", pathname, options),
    post: (pathname, options) => request("POST", pathname, options),
    request,
    setCookie(name, value) {
      jar.set(name, value);
    },
    clearCookies() {
      jar.clear();
    },
  };
}

/* -------------------------------------------------------------------------------------------------
 * Reporting
 * ---------------------------------------------------------------------------------------------- */

export function createReporter(group) {
  const results = [];
  const startedAt = Date.now();

  function record(id, name, status, detail) {
    results.push({ id, name, status, detail });
    const mark = status === "PASS" ? "PASS" : status === "FAIL" ? "FAIL" : "SKIP";
    log(`  ${mark}  ${id.padEnd(6)} ${name}${detail ? ` — ${detail}` : ""}`);
  }

  function assert(condition, message) {
    if (!condition) throw new Error(message);
  }

  async function test(id, name, fn) {
    try {
      const detail = await fn({ assert });
      record(id, name, "PASS", typeof detail === "string" ? detail : detail?.detail);
      return { ok: true, value: detail?.value ?? detail };
    } catch (error) {
      record(id, name, "FAIL", error instanceof Error ? error.message : String(error));
      return { ok: false, error };
    }
  }

  function skip(id, name, detail) {
    record(id, name, "SKIP", detail);
  }

  function summary() {
    const passed = results.filter((r) => r.status === "PASS").length;
    const failed = results.filter((r) => r.status === "FAIL").length;
    const skipped = results.filter((r) => r.status === "SKIP").length;
    const seconds = ((Date.now() - startedAt) / 1000).toFixed(1);
    log("");
    log(`  Group ${group}: ${passed} passed, ${failed} failed, ${skipped} skipped in ${seconds}s`);
    return { passed, failed, skipped, results, seconds };
  }

  return { test, skip, assert, summary, results };
}

/** Create a throwaway database name that cannot collide with a real one. */
export function scratchDb(prefix, stamp) {
  return `primemet_m1_${prefix}_${stamp}`.toLowerCase().replace(/[^a-z0-9_]/g, "_").slice(0, 60);
}
